package config

import "testing"

func TestParsePort(t *testing.T) {
    tests := []struct {
        name string
        input string
        want uint16
        wantErr bool
    }{
        {"min", "1", 1, false},
        {"max", "65535", 65535, false},
        {"zero", "0", 0, true},
        {"overflow", "65536", 0, true},
        {"spaces", " 8080 ", 8080, false},
        {"text", "http", 0, true},
        {"empty", "", 0, true},
    }
    for _, tc := range tests {
        t.Run(tc.name, func(t *testing.T) {
            got, err := ParsePort(tc.input)
            if (err != nil) != tc.wantErr { t.Fatalf("error=%v wantErr=%v", err, tc.wantErr) }
            if got != tc.want { t.Fatalf("got=%d want=%d", got, tc.want) }
        })
    }
}

